from bulk import B
B("Sharks & rays","🦈",[
("tiger-shark","Tiger shark","Galeocerdo cuvier",0,350,["Tropical & warm-temperate worldwide"],"Up to ~5 m","~30 years","Generalist: turtles, fish, birds, carrion","Near Threatened","The ocean's great generalist, known for eating almost anything including sea turtles and debris.","Coastal reefs, lagoons and open shelf waters; warm seas.","Cruise-and-ambush hunter that patrols reefs at night; serrated teeth saw through turtle shells.","Aplacental viviparity-like (yolk-sac with embryotrophy); litters of 10–80 pups after ~15 months.","Long seasonal migrations tracked by satellite tags, e.g. Hawaii to open ocean and back.","Mostly solitary; nocturnal hunting peaks; deep dives by day."),
("hammerhead-great","Great hammerhead","Sphyrna mokarran",1,300,["Tropical worldwide"],"Up to 6 m","20–44 years","Stingrays, other sharks, bony fish","Critically Endangered","The largest hammerhead, whose wide head (cephalofoil) is a sensor array and a weapon for pinning rays.","Coastal and offshore warm waters, reefs, continental shelves.","Sweeps the seabed with electroreceptors spread across its head, then pins stingrays down with it.","Viviparous with a yolk-sac placenta; 6–42 pups every two years.","Nomadic, migrating poleward in summer.","Solitary; swims on its side to save energy."),
("scalloped-hammerhead","Scalloped hammerhead","Sphyrna lewini",0,1000,["Tropical & warm-temperate worldwide"],"Up to 4 m","~30 years","Fish, squid, rays","Critically Endangered","Famous for forming huge daytime schools around seamounts like Cocos and the Galápagos.","Coastal and seamount waters; juveniles in shallow nursery bays.","Hunts at night, diving to 1,000 m for squid; schools rest by day.","Placental viviparity; 12–41 pups.","Commutes nightly from seamount schools to open-ocean feeding grounds.","Highly social schools with a dominance hierarchy; females compete for central positions."),
("bull-shark","Bull shark","Carcharhinus leucas",0,150,["Warm coasts worldwide; rivers and lakes"],"Up to 3.5 m","~16 years","Fish, sharks, turtles, birds","Vulnerable","A shark that can live in fresh water, found 4,000 km up the Amazon and in Lake Nicaragua.","Shallow coasts, estuaries, rivers; tolerates salinity from fresh to marine.","Opportunistic predator in murky water using the 'bump-and-bite' approach.","Placental viviparity; pups born in low-salinity river mouths that act as nurseries.","Moves between rivers, estuaries and sea; seasonal latitude shifts.","Solitary and aggressive; kidneys and rectal gland adjust salt balance."),
("blue-shark","Blue shark","Prionace glauca",0,1000,["Open ocean worldwide"],"Up to 3.8 m","~20 years","Squid, small fish","Near Threatened","A slender, wide-ranging ocean wanderer and the most heavily fished shark on Earth.","Open ocean, temperate and tropical; often in cooler surface water.","Feeds heavily on squid, diving to depth at night and by day.","Placental viviparity; very large litters (up to 135 pups).","Trans-oceanic migrations following the Gulf Stream circuit around the North Atlantic.","Segregates by sex and size; females have thicker skin to survive mating bites."),
("shortfin-mako","Shortfin mako","Isurus oxyrinchus",0,500,["Tropical & temperate worldwide"],"Up to 4 m","~30 years","Tuna, swordfish, other sharks","Endangered","The fastest shark, with bursts estimated around 50–70 km/h and spectacular leaps.","Open ocean and continental shelf edges.","High-speed pursuit predator of tuna and billfish; regionally warm-bodied (red muscle heat exchangers).","Oophagy: embryos eat unfertilised eggs; 4–25 pups after 15–18 months.","Long migrations across ocean basins.","Solitary, highly active; jumps several metres out of the water."),
("oceanic-whitetip","Oceanic whitetip shark","Carcharhinus longimanus",0,230,["Tropical open ocean worldwide"],"Up to 3.5 m","~25 years","Fish, squid, carrion","Critically Endangered","Once among the most abundant large animals on Earth; populations have collapsed by over 95% in places.","Warm, blue open ocean far from land.","Persistent opportunist; investigates anything, including shipwreck survivors.","Placental viviparity; 1–15 pups.","Follows warm water seasonally.","Slow, bold and curious; often accompanied by pilot fish."),
("basking-shark","Basking shark","Cetorhinus maximus",0,1260,["Temperate seas worldwide"],"Up to 10 m","~50 years","Zooplankton (filter feeder)","Endangered","The second-largest fish, cruising with its mouth wide open to filter plankton.","Temperate coastal and shelf waters; deep water in winter.","Ram filter feeder sieving up to ~2,000 tonnes of water an hour through gill rakers.","Ovoviviparous; gestation possibly over 2 years; rarely observed.","Seasonal migrations; some cross the equator at depth.","Seen in groups at fronts; courtship behaviour observed off Ireland."),
("megamouth-shark","Megamouth shark","Megachasma pelagios",0,1500,["Tropical & temperate worldwide"],"Up to 5.5 m","Unknown","Krill, jellyfish, copepods","Least Concern","One of the rarest sharks known, discovered only in 1976 and seen fewer than 300 times.","Open ocean, migrating between depth and surface.","Slow filter feeder with a huge mouth; lips may be reflective to lure prey.","Presumed ovoviviparous with oophagy.","Diel vertical migration: ~120–160 m by day, ~12–25 m at night.","Rarely seen; behaviour inferred from a few tagged animals."),
("cookiecutter-shark","Cookiecutter shark","Isistius brasiliensis",0,3700,["Tropical open ocean worldwide"],"~50 cm","Unknown","Plugs of flesh from large animals","Least Concern","A tiny shark that bites perfect round plugs from whales, tuna and even submarine sonar domes.","Open ocean, migrating from deep water to the surface at night.","Glowing underside lures predators; it latches on with sucker lips and spins to cut a plug.","Ovoviviparous; 6–12 pups.","Daily vertical migration of up to 3 km.","Bioluminescent except a dark collar that may mimic a small fish."),
("lantern-shark","Dwarf lanternshark","Etmopterus perryi",283,439,["Caribbean off Colombia and Venezuela"],"~20 cm","Unknown","Krill, small shrimp","Least Concern","Possibly the smallest shark in the world, glowing with photophores on its belly.","Upper continental slopes.","Hunts tiny crustaceans in dim water using large eyes.","Ovoviviparous; litters of 2–3.","Unknown.","Counter-illumination camouflage from belly photophores."),
("sixgill-shark","Bluntnose sixgill shark","Hexanchus griseus",0,2500,["Worldwide temperate & tropical"],"Up to 5.5 m","~80 years","Fish, seals, carrion","Near Threatened","An ancient deep-sea shark with six gill slits, a lineage almost unchanged for ~200 million years.","Continental slopes and deep basins; rises at night.","Scavenger and active predator at depth.","Ovoviviparous; very large litters (up to 108).","Diel vertical migration; comes shallower at night.","Sluggish but powerful; often seen at whale falls."),
("sleeper-shark-pacific","Pacific sleeper shark","Somniosus pacificus",0,2000,["North Pacific"],"Up to 7 m","Very long (centuries?)","Fish, squid, seals, carrion","Data Deficient","A huge, slow cold-water shark and Pacific relative of the Greenland shark.","Cold shelf and slope waters, deep in the south of its range.","Slow-moving scavenger and ambush predator; even eats giant Pacific octopus.","Ovoviviparous; up to ~300 eggs recorded.","Moves vertically with temperature.","Extremely slow swimmer, saving energy in cold water."),
("zebra-shark","Zebra shark","Stegostoma tigrinum",0,62,["Indo-Pacific"],"Up to 2.5 m","~25–30 years","Molluscs, crustaceans, small fish","Endangered","Spotted as adults but striped as juveniles; known for virgin births in aquaria.","Coral reefs and sandy flats.","Wriggles into crevices and sucks out prey.","Oviparous; capable of parthenogenesis.","Mostly resident; some seasonal aggregations.","Rests on the bottom by day, active at night."),
("nurse-shark","Nurse shark","Ginglymostoma cirratum",1,130,["Atlantic & eastern Pacific"],"Up to 3 m","~25 years","Crustaceans, molluscs, fish","Vulnerable","A bottom-dwelling shark that sucks prey out of holes with powerful suction.","Shallow reefs, mangroves, seagrass.","Suction feeder that can pump water over its gills while resting.","Ovoviviparous; mating aggregations in shallow water.","Site-faithful, returning to the same mating grounds.","Rests in piles of individuals under ledges by day."),
("wobbegong","Tasselled wobbegong","Eucrossorhinus dasypogon",0,40,["Western Pacific, northern Australia"],"Up to 1.8 m","Unknown","Fish, crustaceans","Least Concern","A carpet shark with a fringe of skin flaps that turns it into a perfect ambush rug.","Coral reefs and lagoons.","Camouflaged ambush predator; may wave its tail like a lure.","Ovoviviparous.","Resident.","Lies motionless under ledges for long periods."),
("epaulette-shark","Epaulette shark","Hemiscyllium ocellatum",0,50,["Northern Australia, New Guinea"],"~1 m","~20–25 years","Worms, crabs, small fish","Least Concern","The 'walking shark' that crawls between tide pools on its fins and survives low oxygen.","Shallow reef flats and tide pools.","Walks across reef flats probing for invertebrates.","Oviparous; egg cases hatch after ~4 months.","Resident.","Tolerates hypoxia for hours by lowering brain activity."),
("port-jackson-shark","Port Jackson shark","Heterodontus portusjacksoni",0,275,["Southern Australia"],"Up to 1.65 m","~30 years","Sea urchins, molluscs, crustaceans","Least Concern","A bullhead shark that lays spiral, screw-shaped egg cases wedged into rocks.","Rocky reefs and sandy bottoms.","Crushing molar-like teeth crack shellfish and urchins.","Oviparous; spiral egg cases.","Annual migrations hundreds of km to breeding reefs.","Nocturnal; returns to the same caves each year."),
("angel-shark","Angelshark","Squatina squatina",0,150,["NE Atlantic, Mediterranean, Canary Islands"],"Up to 2.4 m","~35 years","Flatfish, skates, molluscs","Critically Endangered","A flattened shark that buries itself in sand; now rare except around the Canary Islands.","Sandy and muddy coastal seabeds.","Ambush predator that bursts from the sand in a fraction of a second.","Ovoviviparous; 7–25 pups.","Seasonal inshore-offshore movements.","Sedentary by day; active at night."),
("spotted-eagle-ray","Spotted eagle ray","Aetobatus narinari",1,80,["Tropical Atlantic & Indo-Pacific"],"Up to 3 m wingspan","~25 years","Clams, oysters, snails","Endangered","A graceful ray with a duck-bill snout and white-spotted back, often seen leaping.","Coastal reefs, bays and lagoons.","Digs molluscs from sand with its snout and crushes them with plate-like teeth.","Ovoviviparous; up to 4 pups.","Coastal movements; sometimes in large schools.","Leaps out of the water; schools during migration.", "Spotted_eagle_ray"),
("mobula-ray","Munk's devil ray","Mobula munkiana",0,30,["Eastern Pacific"],"~1.1 m wingspan","Unknown","Zooplankton","Vulnerable","Gathers in schools of thousands in the Gulf of California and leaps several metres into the air.","Coastal and offshore waters.","Filter feeds on mysid shrimp and zooplankton.","Ovoviviparous; one pup.","Seasonal mass aggregations.","Spectacular 'flying' leaps, possibly for communication or courtship."),
("reef-manta","Reef manta ray","Mobula alfredi",0,450,["Indo-Pacific"],"Up to 5 m wingspan","~40 years","Zooplankton","Vulnerable","Visits 'cleaning stations' on reefs where small fish pick it clean; recognised individually by belly spots.","Coastal reefs and islands.","Cyclone feeding: whole groups spiral to concentrate plankton.","One pup every 2–5 years.","Site-faithful with regional movements.","Highly intelligent; one of the largest brain-to-body ratios among fish."),
("sawfish-smalltooth","Smalltooth sawfish","Pristis pectinata",0,120,["Atlantic"],"Up to 7 m","~30 years","Fish, crustaceans","Critically Endangered","A ray with a toothed saw that senses and slashes prey; once common, now vanished from most of its range.","Shallow coasts, mangroves and estuaries.","Saw contains electroreceptors; swipes to stun and pin fish.","Ovoviviparous; 7–14 pups.","Juveniles stay in mangrove nurseries.","Slow; easily entangled in nets."),
("electric-ray","Atlantic torpedo","Tetronarce nobiliana",2,800,["Atlantic, Mediterranean"],"Up to 1.8 m","Unknown","Fish","Least Concern","Delivers shocks of up to ~220 volts from paired electric organs to stun prey.","Sandy seabeds and open water.","Envelops fish and stuns them with electric discharges.","Ovoviviparous.","Some movement between coast and open sea.","Mostly buried in sand by day."),
("stingray-southern","Southern stingray","Hypanus americanus",0,53,["Western Atlantic, Caribbean"],"Up to 1.5 m","~15–20 years","Clams, worms, small fish","Near Threatened","A classic sand-flat stingray famous at Grand Cayman's 'Stingray City'.","Shallow sandy flats, seagrass, reefs.","Excavates buried prey with water jets from its mouth.","Ovoviviparous; 2–10 pups.","Local movements.","Often followed by jacks that grab disturbed prey."),
("chimaera-ghost-shark","Spotted ratfish","Hydrolagus colliei",0,971,["NE Pacific"],"Up to 1 m","Unknown","Clams, crabs, worms","Least Concern","A chimaera ('ghost shark'), part of an ancient cartilaginous lineage separate from sharks for ~400 million years.","Continental shelf and slope.","Grinds shellfish with tooth plates.","Oviparous; males have a retractable clasper on the forehead.","Moves shallower at night.","Venomous spine in front of the dorsal fin."),
])
